/** void BufferBattleTowerElevatorFloors(void) */
export function BufferBattleTowerElevatorFloors(): any {
  const sBattleTowerStreakThresholds: any = [
          7, 14, 21, 28, 35, 49, 63, 77, 91, 0
      ];

      let i: any = null;
      let battleMode: any = VarGet((0x40CE));
      let lvlMode: any = gSaveBlock2Ptr.frontier.lvlMode;

      if (battleMode == (3))  
      {
          gSpecialVar_0x8005 = 4;
          gSpecialVar_0x8006 = 5;
          return;
      }

      if (battleMode == (2) && !FlagGet((0x152)))
      {
          gSpecialVar_0x8005 = 5;
          gSpecialVar_0x8006 = 4;
          return;
      }

      for (i = 0; i < ARRAY_COUNT(sBattleTowerStreakThresholds) - 1; i++)
      {
          if (sBattleTowerStreakThresholds[i] > gSaveBlock2Ptr.frontier.towerWinStreaks[battleMode][lvlMode])
          {
              gSpecialVar_0x8005 = 4;
              gSpecialVar_0x8006 = i + 5;
              return;
          }
      }

      gSpecialVar_0x8005 = 4;
      gSpecialVar_0x8006 = 12;
}

