/** static void Task_LinkRetireStatusWithBattleTowerPartner(u8 taskId) */
export function Task_LinkRetireStatusWithBattleTowerPartner(taskId: any): any {
  switch (gTasks[taskId].tState)
      {
      case 0:
          if (!FuncIsActiveTask(Task_ReconnectWithLinkPlayers))
              gTasks[taskId].tState++;
          break;
      case 1:
          if (IsLinkTaskFinished() == TRUE)
          {
              if (GetMultiplayerId() == 0)
              {
                   
                  gTasks[taskId].tState++;
              }
              else
              {
                   
                   
                  SendBlock(BitmaskAllOtherLinkPlayers(),gSpecialVar_0x8004, 0);
                  gTasks[taskId].tState++;
              }
          }
          break;
      case 2:
          if (GetBlockReceivedStatus() & 2)
          {
              if (GetMultiplayerId() == 0)
              {
                   
                   
                  gSpecialVar_0x8005 = gBlockRecvBuffer[1][0];
                  ResetBlockReceivedFlag(1);

                  if (gSpecialVar_0x8004 == (1)
                   && gSpecialVar_0x8005 == (1))
                      gSpecialVar_Result = (1);
                  else if (gSpecialVar_0x8004 == (0)
                        && gSpecialVar_0x8005 == (1))
                      gSpecialVar_Result = (2);
                  else if (gSpecialVar_0x8004 == (1)
                        && gSpecialVar_0x8005 == (0))
                      gSpecialVar_Result = (3);
                  else
                      gSpecialVar_Result = (0);
              }
              gTasks[taskId].tState++;
          }
          break;
      case 3:
          if (IsLinkTaskFinished() == TRUE)
          {
              if (GetMultiplayerId() != 0)
              {
                   
                  gTasks[taskId].tState++;
              }
              else
              {
                   
                  SendBlock(BitmaskAllOtherLinkPlayers(),gSpecialVar_Result, 0);
                  gTasks[taskId].tState++;
              }
          }
          break;
      case 4:
          if (GetBlockReceivedStatus() & 1)
          {
              if (GetMultiplayerId() != 0)
              {
                   
                  gSpecialVar_Result = gBlockRecvBuffer[0][0];
                  ResetBlockReceivedFlag(0);
                  gTasks[taskId].tState++;
              }
              else
              {
                  gTasks[taskId].tState++;
              }
          }
          break;
      case 5:
           
          if (GetMultiplayerId() == 0)
          {
              if (gSpecialVar_Result == (2))
                  ShowFieldAutoScrollMessage(gText_YourPartnerHasRetired);
          }
          else
          {
              if (gSpecialVar_Result == (3))
                  ShowFieldAutoScrollMessage(gText_YourPartnerHasRetired);
          }
          gTasks[taskId].tState++;
          break;
      case 6:
          if (!IsTextPrinterActive(0))
              gTasks[taskId].tState++;
          break;
      case 7:
          if (IsLinkTaskFinished() == TRUE)
          {
              SetLinkStandbyCallback();
              gTasks[taskId].tState++;
          }
          break;
      case 8:
          if (IsLinkTaskFinished() == TRUE)
              gTasks[taskId].tState++;
          break;
      case 9:
          if (gWirelessCommType == 0)
              SetCloseLinkCallback();

          gBattleTypeFlags = sBattleTowerMultiBattleTypeFlags;
          ScriptContext_Enable();
          DestroyTask(taskId);
          break;
      }
}

